// Scan2Skip Logo - embedded PNG as base64 data URI
(function() {
  var LOGO_SRC = 'data:image/png;base64,';
  function applyLogo() {
    document.querySelectorAll('.sidebar-logo, .login-logo').forEach(function(img) {
      img.src = LOGO_SRC;
    });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', applyLogo);
  } else {
    applyLogo();
  }
})();